import { useMemo, useState } from 'react';
import { BarChart3 } from 'lucide-react';

const PurchaseInsightsPanel = ({
  operationsSummary,
  rollupParams,
  setRollupParams,
  rollupRangeLabel,
  toNumber,
}) => {
  const [pendingRollupRange, setPendingRollupRange] = useState({
    start_date: '',
    end_date: '',
  });
  const [rollupChartMode, setRollupChartMode] = useState('total');

  const actionRollups = operationsSummary?.action_rollups || {};
  const rollupActions = actionRollups.actions || [];
  const rollupWeekdays = actionRollups.by_weekday || [];
  const rollupDays = actionRollups.by_day || [];
  const rollupTotals = actionRollups.totals || {};
  const rollupRecentDays = rollupDays.slice(-10);

  const chartSeries = useMemo(() => (rollupChartMode === 'total'
    ? [
        {
          key: 'total',
          label: 'Total Actions',
          getValue: (entry) => rollupActions.reduce((sum, action) => sum + toNumber(entry[action.key]), 0),
        },
      ]
    : rollupActions.map((action) => ({
      key: action.key,
      label: action.label,
      getValue: (entry) => toNumber(entry[action.key]),
    }))
  ), [rollupChartMode, rollupActions, toNumber]);

  const maxChartValue = Math.max(
    1,
    ...rollupWeekdays.map((entry) => {
      if (rollupChartMode === 'actions') {
        return rollupActions.reduce((sum, action) => sum + toNumber(entry[action.key]), 0);
      }
      return Math.max(...chartSeries.map((series) => series.getValue(entry)));
    })
  );

  const handleRollupPresetChange = (event) => {
    const value = event.target.value;
    if (value === 'custom') {
      setRollupParams((prev) => ({ ...prev, mode: 'custom' }));
      return;
    }
    const days = Number(value || 30);
    setRollupParams((prev) => ({
      ...prev,
      mode: String(days),
      days,
    }));
  };

  const handleApplyCustomRange = () => {
    setRollupParams((prev) => ({
      ...prev,
      mode: 'custom',
      start_date: pendingRollupRange.start_date,
      end_date: pendingRollupRange.end_date,
    }));
  };

  const handleDownloadRollupCsv = () => {
    if (!rollupDays.length) return;
    const headers = ['date', 'weekday', ...rollupActions.map((action) => action.key)];
    const lines = [
      headers.join(','),
      ...rollupDays.map((row) => [
        row.date,
        row.weekday,
        ...rollupActions.map((action) => toNumber(row[action.key])),
      ].join(',')),
    ];
    const csv = lines.join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `purchase-rollups-${actionRollups.range?.start_date || 'start'}-to-${actionRollups.range?.end_date || 'end'}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const renderRollupTable = (rows, labelKey, labelTitle, showTotals = false) => (
    <div className="purchase-ops-table-wrap">
      <table className="purchase-ops-table">
        <thead>
          <tr>
            <th>{labelTitle}</th>
            {rollupActions.map((action) => (
              <th key={action.key}>{action.label}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.length ? rows.map((row) => (
            <tr key={`${labelKey}-${row[labelKey]}`}>
              <td>{row[labelKey] || '-'}</td>
              {rollupActions.map((action) => (
                <td key={`${row[labelKey]}-${action.key}`}>{toNumber(row[action.key])}</td>
              ))}
            </tr>
          )) : (
            <tr>
              <td colSpan={1 + rollupActions.length}>No rollup data for this range.</td>
            </tr>
          )}
          {showTotals && rollupActions.length ? (
            <tr className="purchase-ops-table-total">
              <td>Total</td>
              {rollupActions.map((action) => (
                <td key={`total-${action.key}`}>{toNumber(rollupTotals[action.key])}</td>
              ))}
            </tr>
          ) : null}
        </tbody>
      </table>
    </div>
  );

  return (
    <div className="purchase-sector-grid single">
      <section className="purchase-ops-panel insights">
        <div className="purchase-ops-panel-title">
          <BarChart3 size={16} />
          <span>Action Rollups</span>
        </div>
        <div className="purchase-ops-rollup-meta">Range: {rollupRangeLabel}</div>
        <div className="purchase-ops-rollup-controls">
          <label>
            Range
            <select value={rollupParams?.mode || '30'} onChange={handleRollupPresetChange}>
              <option value="7">Last 7 days</option>
              <option value="30">Last 30 days</option>
              <option value="90">Last 90 days</option>
              <option value="custom">Custom</option>
            </select>
          </label>
          <label>
            Chart
            <select value={rollupChartMode} onChange={(event) => setRollupChartMode(event.target.value)}>
              <option value="total">Total actions</option>
              <option value="actions">By action</option>
            </select>
          </label>
          <button type="button" className="admin-btn secondary small" onClick={handleDownloadRollupCsv}>
            Download CSV
          </button>
          {rollupParams?.mode === 'custom' ? (
            <div className="purchase-ops-rollup-custom">
              <label>
                Start
                <input
                  type="date"
                  value={pendingRollupRange.start_date}
                  onChange={(event) => setPendingRollupRange((prev) => ({ ...prev, start_date: event.target.value }))}
                />
              </label>
              <label>
                End
                <input
                  type="date"
                  value={pendingRollupRange.end_date}
                  onChange={(event) => setPendingRollupRange((prev) => ({ ...prev, end_date: event.target.value }))}
                />
              </label>
              <button type="button" className="admin-btn secondary small" onClick={handleApplyCustomRange}>
                Apply
              </button>
            </div>
          ) : null}
        </div>
        <div className={`purchase-ops-rollup-chart ${rollupChartMode === 'actions' ? 'stacked' : ''}`}>
          {rollupWeekdays.map((entry) => (
            <div key={entry.weekday} className="purchase-ops-rollup-bar">
              <span>{entry.weekday.slice(0, 3)}</span>
              <div className="bar-track">
                {chartSeries.map((series) => {
                  const value = series.getValue(entry);
                  const width = (value / maxChartValue) * 100;
                  return (
                    <div
                      key={`${entry.weekday}-${series.key}`}
                      className={`bar-fill ${series.key}`}
                      style={{ width: `${width}%` }}
                      title={`${series.label}: ${value}`}
                    />
                  );
                })}
              </div>
              <strong>{chartSeries.reduce((sum, series) => sum + series.getValue(entry), 0)}</strong>
            </div>
          ))}
        </div>
        <div className="purchase-ops-rollup-grid">
          <div>
            <h4>Weekday</h4>
            {renderRollupTable(rollupWeekdays, 'weekday', 'Weekday', true)}
          </div>
          <div>
            <h4>Recent Days</h4>
            {renderRollupTable(rollupRecentDays, 'date', 'Date', false)}
          </div>
        </div>
      </section>
    </div>
  );
};

export default PurchaseInsightsPanel;

import { useCallback, useMemo } from 'react';
import { getPurchaseDraftDiagnostics } from '../utils/orderDraftValidation';

function useOrderDetailComputed({
  orderDetail,
  orderDetailDraft,
  orderDetailEditMode,
  products,
  findProductForItem,
  calculateOrderItem,
  toNumber,
  formatCurrency,
  normalizeGstRateOption,
  calculateOrderTotals,
  getOrderDisplayTotal,
  toDateInputValue,
}) {
  const orderDetailItems = orderDetailEditMode ? (orderDetailDraft?.items || []) : (orderDetail?.items || []);
  const orderDetailOriginalItems = orderDetail?.items || [];

  const getOrderDetailOriginalItem = useCallback((draftItem, index) => {
    if (draftItem?.id) {
      const byId = orderDetailOriginalItems.find((item) => String(item?.id || '') === String(draftItem.id));
      if (byId) return byId;
    }
    return orderDetailOriginalItems[index] || null;
  }, [orderDetailOriginalItems]);

  const hasOrderDetailItemChanged = useCallback((draftItem, index) => {
    const originalItem = getOrderDetailOriginalItem(draftItem, index);
    if (!originalItem) return true;
    return (
      String(draftItem?.product_id || '') !== String(originalItem?.product_id || '') ||
      String(draftItem?.uom || '') !== String(originalItem?.uom || '') ||
      Math.abs(toNumber(draftItem?.quantity) - toNumber(originalItem?.quantity)) > 0.0001 ||
      Math.abs(toNumber(draftItem?.rate ?? draftItem?.unit_price) - toNumber(originalItem?.rate ?? originalItem?.unit_price)) > 0.0001 ||
      Math.abs(toNumber(draftItem?.gst_rate) - toNumber(originalItem?.gst_rate)) > 0.0001 ||
      String(draftItem?.discount_type || 'percent') !== String(originalItem?.discount_type || 'percent') ||
      Math.abs(toNumber(draftItem?.discount_value) - toNumber(originalItem?.discount_value)) > 0.0001
    );
  }, [getOrderDetailOriginalItem, toNumber]);

  const getOrderDetailItemFieldChanged = useCallback((draftItem, index, field) => {
    const originalItem = getOrderDetailOriginalItem(draftItem, index);
    if (!originalItem) return true;
    if (field === 'product_id') {
      return String(draftItem?.product_id || '') !== String(originalItem?.product_id || '');
    }
    if (field === 'uom') {
      return String(draftItem?.uom || '') !== String(originalItem?.uom || '');
    }
    if (field === 'quantity') {
      return Math.abs(toNumber(draftItem?.quantity) - toNumber(originalItem?.quantity)) > 0.0001;
    }
    if (field === 'rate') {
      return Math.abs(toNumber(draftItem?.rate ?? draftItem?.unit_price) - toNumber(originalItem?.rate ?? originalItem?.unit_price)) > 0.0001;
    }
    if (field === 'gst_rate') {
      return Math.abs(toNumber(draftItem?.gst_rate) - toNumber(originalItem?.gst_rate)) > 0.0001;
    }
    if (field === 'discount_type') {
      return String(draftItem?.discount_type || 'percent') !== String(originalItem?.discount_type || 'percent');
    }
    if (field === 'discount_value') {
      return Math.abs(toNumber(draftItem?.discount_value) - toNumber(originalItem?.discount_value)) > 0.0001;
    }
    return false;
  }, [getOrderDetailOriginalItem, toNumber]);

  const getOrderDetailItemOriginalLabel = useCallback((draftItem, index, field) => {
    const originalItem = getOrderDetailOriginalItem(draftItem, index);
    if (!originalItem) return 'New item';
    if (field === 'product_id') return String(originalItem?.product_name || '-');
    if (field === 'uom') return String(originalItem?.uom || '-');
    if (field === 'quantity') return String(toNumber(originalItem?.quantity));
    if (field === 'rate') return formatCurrency(toNumber(originalItem?.rate ?? originalItem?.unit_price));
    if (field === 'gst_rate') return `${normalizeGstRateOption(originalItem?.gst_rate).toFixed(0)}%`;
    if (field === 'discount_type') return String(originalItem?.discount_type === 'fixed' ? 'Fixed' : '%');
    if (field === 'discount_value') return String(toNumber(originalItem?.discount_value));
    return '-';
  }, [formatCurrency, getOrderDetailOriginalItem, normalizeGstRateOption, toNumber]);

  const orderDetailHasComputedChanges = useMemo(() => orderDetailEditMode && (
    String(orderDetailDraft?.expected_delivery || '') !== toDateInputValue(orderDetail?.expected_delivery) ||
    String(orderDetailDraft?.strict_due_date || '') !== toDateInputValue(orderDetail?.strict_due_date) ||
    String(orderDetailDraft?.notes || '') !== String(orderDetail?.notes || '') ||
    String(orderDetailDraft?.strict_due_note || '') !== String(orderDetail?.strict_due_note || '') ||
    orderDetailItems.length !== orderDetailOriginalItems.length ||
    orderDetailItems.some((item, index) => hasOrderDetailItemChanged(item, index))
  ), [
    orderDetailEditMode,
    orderDetailDraft?.expected_delivery,
    orderDetailDraft?.strict_due_date,
    orderDetailDraft?.notes,
    orderDetailDraft?.strict_due_note,
    orderDetail?.expected_delivery,
    orderDetail?.strict_due_date,
    orderDetail?.notes,
    orderDetail?.strict_due_note,
    orderDetailItems,
    orderDetailOriginalItems.length,
    hasOrderDetailItemChanged,
    toDateInputValue,
  ]);

  const orderDetailComputedTotals = useMemo(() => (
    orderDetailEditMode
      ? calculateOrderTotals(orderDetailItems)
      : {
          taxableValue: toNumber(orderDetail?.taxable_value),
          taxAmount: toNumber(orderDetail?.tax_amount),
          totalAmount: toNumber(orderDetail?.total_amount || getOrderDisplayTotal(orderDetail)),
        }
  ), [
    orderDetailEditMode,
    orderDetailItems,
    calculateOrderTotals,
    orderDetail?.taxable_value,
    orderDetail?.tax_amount,
    orderDetail?.total_amount,
    orderDetail,
    getOrderDisplayTotal,
    toNumber,
  ]);

  const orderDetailDraftDiagnostics = useMemo(() => getPurchaseDraftDiagnostics({
    items: orderDetailEditMode
      ? orderDetailItems
      : orderDetailItems.map((item) => ({
          ...item,
          rate_warning_acknowledged: true,
          discount_warning_acknowledged: true,
        })),
    products,
    findProductForItem,
    calculateOrderItem,
  }), [
    orderDetailEditMode,
    orderDetailItems,
    products,
    findProductForItem,
    calculateOrderItem,
  ]);

  return {
    orderDetailItems,
    orderDetailOriginalItems,
    getOrderDetailOriginalItem,
    hasOrderDetailItemChanged,
    getOrderDetailItemFieldChanged,
    getOrderDetailItemOriginalLabel,
    orderDetailHasComputedChanges,
    orderDetailComputedTotals,
    orderDetailDraftDiagnostics,
  };
}

export default useOrderDetailComputed;

import { useCallback } from 'react';
import { DOMAINS, invalidateDomain } from '../../../../shared/services/invalidation';
import { getSignedLedgerAmount } from '../../../../shared/utils/ledger';
import { validateAmountInput } from '../../../../shared/utils/amountExpression';

const usePurchaseLedgerCorrections = ({
  distributorLedgerApi,
  calculateOrderBalanceAmount,
  toNumber,
  normalizeTextKey,
  getDefaultPoCorrectionFormData,
  getDefaultLedgerFormData,
  setShowPoCorrectionForm,
  setSelectedCorrectionOrder,
  setPoCorrectionFormData,
  setPoCorrectionContext,
  setPoCorrectionSubmitting,
  poCorrectionLockRef,
  selectedCorrectionOrder,
  poCorrectionSubmitting,
  poCorrectionFormData,
  setError,
  fetchDistributorLedger,
  user,
  setShowLedgerForm,
  setLedgerFormData,
  setLedgerSubmitting,
  ledgerSubmitLockRef,
  ledgerSubmitting,
  ledgerFormData,
  addLocalLedgerEntry,
  localLedgerKey,
  filters,
}) => {
  const getLedgerRowsFromResponse = useCallback((response) => {
    if (Array.isArray(response)) return response;
    return response?.rows || response?.data || response?.transactions || [];
  }, []);

  const getPoLinkedLedgerRows = useCallback((rows, order) => {
    if (!order) return [];

    const orderId = String(order.id || '').trim();
    const poNumberKey = normalizeTextKey(order.po_number);

    return (rows || []).filter((entry) => {
      const source = normalizeTextKey(entry?.source);
      const sourceId = entry?.source_id ?? entry?.sourceId;
      if (
        (source === 'purchase_order' || source === 'po_correction')
        && sourceId !== undefined
        && sourceId !== null
        && String(sourceId).trim() === orderId
      ) {
        return true;
      }

      const referenceKey = normalizeTextKey(entry?.reference || entry?.po_number);
      if (!poNumberKey || !referenceKey || referenceKey !== poNumberKey) return false;
      const descriptionKey = normalizeTextKey(entry?.description);
      return (
        descriptionKey.includes('purchase order')
        || descriptionKey.includes('po correction')
        || descriptionKey.includes('ledger correction')
      );
    });
  }, [normalizeTextKey]);

  const getPoLedgerImpact = useCallback((rows, order) => (
    getPoLinkedLedgerRows(rows, order).reduce((sum, entry) => sum + getSignedLedgerAmount(entry), 0)
  ), [getPoLinkedLedgerRows]);

  const closePoCorrectionForm = useCallback(() => {
    setShowPoCorrectionForm(false);
    setSelectedCorrectionOrder(null);
    setPoCorrectionFormData(getDefaultPoCorrectionFormData());
    setPoCorrectionContext({
      expectedAmount: 0,
      currentImpact: 0,
      delta: 0,
      linkedEntries: 0,
    });
    setPoCorrectionSubmitting(false);
    poCorrectionLockRef.current = false;
  }, [
    setShowPoCorrectionForm,
    setSelectedCorrectionOrder,
    setPoCorrectionFormData,
    getDefaultPoCorrectionFormData,
    setPoCorrectionContext,
    setPoCorrectionSubmitting,
    poCorrectionLockRef,
  ]);

  const handleOpenPoCorrectionForm = useCallback(async (order) => {
    if (!order || !order.distributor_id) {
      setError('Cannot open correction form. Invalid purchase order/distributor.');
      return;
    }

    try {
      setError('');
      setPoCorrectionSubmitting(true);
      poCorrectionLockRef.current = false;

      const response = await distributorLedgerApi.getByDistributor(order.distributor_id, { limit: 500 });
      const rows = getLedgerRowsFromResponse(response);
      const linkedRows = getPoLinkedLedgerRows(rows, order);
      const expectedAmount = calculateOrderBalanceAmount(order);
      const currentImpact = getPoLedgerImpact(rows, order);
      const delta = Number((expectedAmount - currentImpact).toFixed(2));
      const suggestedType = delta < 0 ? 'payment' : 'credit';
      const suggestedAmount = Math.abs(delta);

      setSelectedCorrectionOrder(order);
      setPoCorrectionContext({
        expectedAmount,
        currentImpact,
        delta,
        linkedEntries: linkedRows.length,
      });
      setPoCorrectionFormData({
        ...getDefaultPoCorrectionFormData(),
        type: suggestedType,
        amount: suggestedAmount > 0 ? suggestedAmount.toFixed(2) : '',
        reference: order.po_number || '',
      });
      setShowPoCorrectionForm(true);
    } catch (err) {
      setError(err?.message || 'Failed to load PO ledger impact for correction');
    } finally {
      setPoCorrectionSubmitting(false);
    }
  }, [
    distributorLedgerApi,
    calculateOrderBalanceAmount,
    getLedgerRowsFromResponse,
    getPoLinkedLedgerRows,
    getPoLedgerImpact,
    getDefaultPoCorrectionFormData,
    setError,
    setPoCorrectionSubmitting,
    poCorrectionLockRef,
    setSelectedCorrectionOrder,
    setPoCorrectionContext,
    setPoCorrectionFormData,
    setShowPoCorrectionForm,
  ]);

  const handlePoCorrectionSubmit = useCallback(async (e) => {
    e.preventDefault();
    if (!selectedCorrectionOrder) return;
    if (poCorrectionSubmitting || poCorrectionLockRef.current) return;
    poCorrectionLockRef.current = true;

    const amountResult = validateAmountInput(poCorrectionFormData.amount, { min: 0 });
    const amount = amountResult.valid ? Number(amountResult.value) : 0;
    const reason = String(poCorrectionFormData.reason || '').trim();
    if (!amountResult.valid || amount <= 0) {
      poCorrectionLockRef.current = false;
      setError(amountResult.message || 'Correction amount must be greater than 0');
      return;
    }
    if (!reason) {
      poCorrectionLockRef.current = false;
      setError('Correction reason is required');
      return;
    }

    try {
      setError('');
      setPoCorrectionSubmitting(true);

      await distributorLedgerApi.addTransaction(selectedCorrectionOrder.distributor_id, {
        type: poCorrectionFormData.type,
        transaction_type: poCorrectionFormData.type,
        amount: Number(amount.toFixed(2)),
        payment_mode: poCorrectionFormData.payment_mode,
        reference: poCorrectionFormData.reference || selectedCorrectionOrder.po_number || '',
        description: `PO correction for ${selectedCorrectionOrder.po_number || selectedCorrectionOrder.id}: ${reason}`,
        transactionDate: poCorrectionFormData.transaction_date,
        source: 'po_correction',
        source_id: selectedCorrectionOrder.id,
        mode: 'manual',
        created_by: user?.id,
      });

      closePoCorrectionForm();
      fetchDistributorLedger();
      await invalidateDomain(DOMAINS.PurchaseOrders, { sourceId: 'purchase-orders' });
      await invalidateDomain(DOMAINS.Ledger, { sourceId: 'purchase-orders' });
    } catch (err) {
      setError(err?.message || 'Failed to post PO correction');
    } finally {
      setPoCorrectionSubmitting(false);
      poCorrectionLockRef.current = false;
    }
  }, [
    selectedCorrectionOrder,
    poCorrectionSubmitting,
    poCorrectionLockRef,
    poCorrectionFormData,
    toNumber,
    setError,
    setPoCorrectionSubmitting,
    distributorLedgerApi,
    user,
    closePoCorrectionForm,
    fetchDistributorLedger,
  ]);

  const handleOpenLedgerForm = useCallback(() => {
    setLedgerFormData({
      ...getDefaultLedgerFormData(),
      distributor_id: filters.distributor_id || '',
    });
    setLedgerSubmitting(false);
    ledgerSubmitLockRef.current = false;
    setShowLedgerForm(true);
  }, [
    setLedgerFormData,
    getDefaultLedgerFormData,
    filters.distributor_id,
    setLedgerSubmitting,
    ledgerSubmitLockRef,
    setShowLedgerForm,
  ]);

  const closeLedgerForm = useCallback(() => {
    setShowLedgerForm(false);
    setLedgerFormData(getDefaultLedgerFormData());
    setLedgerSubmitting(false);
    ledgerSubmitLockRef.current = false;
  }, [
    setShowLedgerForm,
    setLedgerFormData,
    getDefaultLedgerFormData,
    setLedgerSubmitting,
    ledgerSubmitLockRef,
  ]);

  const handleLedgerSubmit = useCallback(async (e) => {
    e.preventDefault();
    if (ledgerSubmitting || ledgerSubmitLockRef.current) return;
    ledgerSubmitLockRef.current = true;
    setError('');

    const amountResult = validateAmountInput(ledgerFormData.amount);
    const amount = amountResult.valid ? Number(amountResult.value) : 0;
    if (!ledgerFormData.distributor_id) {
      ledgerSubmitLockRef.current = false;
      setError('Please select a distributor for ledger entry');
      return;
    }
    if (!amountResult.valid || amount <= 0) {
      ledgerSubmitLockRef.current = false;
      setError(amountResult.message || 'Please enter a valid amount');
      return;
    }

    try {
      setLedgerSubmitting(true);
      await distributorLedgerApi.addTransaction(ledgerFormData.distributor_id, {
        type: ledgerFormData.type,
        transaction_type: ledgerFormData.type,
        amount: Number(amount.toFixed(2)),
        payment_mode: ledgerFormData.payment_mode,
        reference: ledgerFormData.reference,
        description: ledgerFormData.description || `Manual ${ledgerFormData.type} entry`,
        transactionDate: ledgerFormData.transaction_date,
        mode: 'manual',
        created_by: user?.id,
      });

      closeLedgerForm();
      fetchDistributorLedger();
      await invalidateDomain(DOMAINS.PurchaseOrders, { sourceId: 'purchase-orders' });
      await invalidateDomain(DOMAINS.Ledger, { sourceId: 'purchase-orders' });
    } catch (err) {
      const localEntry = {
        id: `local-${Date.now()}`,
        distributor_id: ledgerFormData.distributor_id,
        type: ledgerFormData.type,
        transaction_type: ledgerFormData.type,
        amount: Number(amount.toFixed(2)),
        payment_mode: ledgerFormData.payment_mode,
        reference: ledgerFormData.reference,
        description: ledgerFormData.description || `Manual ${ledgerFormData.type} entry`,
        transaction_date: ledgerFormData.transaction_date,
        created_at: new Date().toISOString(),
        mode: 'manual',
      };
      addLocalLedgerEntry(localLedgerKey, localEntry);
      closeLedgerForm();
      fetchDistributorLedger();
      await invalidateDomain(DOMAINS.PurchaseOrders, { sourceId: 'purchase-orders' });
      await invalidateDomain(DOMAINS.Ledger, { sourceId: 'purchase-orders' });
    } finally {
      setLedgerSubmitting(false);
      ledgerSubmitLockRef.current = false;
    }
  }, [
    ledgerSubmitting,
    ledgerSubmitLockRef,
    toNumber,
    ledgerFormData,
    setError,
    setLedgerSubmitting,
    distributorLedgerApi,
    user,
    closeLedgerForm,
    fetchDistributorLedger,
    addLocalLedgerEntry,
    localLedgerKey,
  ]);

  return {
    getLedgerRowsFromResponse,
    getPoLinkedLedgerRows,
    getPoLedgerImpact,
    closePoCorrectionForm,
    handleOpenPoCorrectionForm,
    handlePoCorrectionSubmit,
    handleOpenLedgerForm,
    closeLedgerForm,
    handleLedgerSubmit,
  };
};

export default usePurchaseLedgerCorrections;

import { useCallback } from 'react';

const normalizeSearchValue = (value) => String(value || '')
  .trim()
  .toLowerCase()
  .replace(/\s+/g, ' ');

const usePurchaseLookups = ({
  distributors,
  suppliers,
  products,
  purchaseOrders,
  buildOrderDraftItem,
  createEmptyOrderItem,
  setOrderFormData,
  resolveProductByInputHelper,
  getDistributorProductOptionsHelper,
  getDistributorProductHistoryEntryHelper,
  getLatestProductHistoryEntryHelper,
  getDistributorHistoryProductsHelper,
}) => {
  const distributorById = new Map(
    (Array.isArray(distributors) ? distributors : []).map((entry) => [String(entry?.id || ''), entry])
  );

  const resolveSupplierByInput = useCallback((value) => {
    const query = normalizeSearchValue(value);
    if (!query) return null;

    const supplierMatches = (Array.isArray(suppliers) ? suppliers : []).find((entry) => {
      const isActive = entry?.is_active !== false;
      if (!isActive) return false;
      const supplierName = normalizeSearchValue(entry?.name || '');
      const distributorName = normalizeSearchValue(
        distributorById.get(String(entry?.distributor_id || ''))?.name || ''
      );
      return (
        String(entry.id) === query
        || supplierName === query
        || `${supplierName} ${distributorName}`.trim() === query
        || `${supplierName} - ${distributorName}`.trim() === query
        || `${distributorName} ${supplierName}`.trim() === query
        || `${distributorName} - ${supplierName}`.trim() === query
      );
    });
    if (supplierMatches) return supplierMatches || null;

    const distributorMatch = Array.from(distributorById.values()).find(
      (entry) => normalizeSearchValue(entry?.name || '') === query
    );
    if (!distributorMatch) return null;

    const distributorSuppliers = (Array.isArray(suppliers) ? suppliers : []).filter((entry) => {
      const isActive = entry?.is_active !== false;
      return isActive && String(entry?.distributor_id || '') === String(distributorMatch.id || '');
    });
    if (distributorSuppliers.length === 1) return distributorSuppliers[0];
    return distributorSuppliers.find((entry) => entry?.is_primary) || null;
  }, [distributorById, suppliers]);

  const resolveProductByInput = useCallback((value) => (
    resolveProductByInputHelper(value, products)
  ), [resolveProductByInputHelper, products]);

  const getDistributorProductOptions = useCallback((distributorId) => (
    getDistributorProductOptionsHelper({
      distributorId,
      products,
      purchaseOrders,
    })
  ), [getDistributorProductOptionsHelper, products, purchaseOrders]);

  const getDistributorProductHistoryEntry = useCallback((distributorId, productId) => (
    getDistributorProductHistoryEntryHelper({
      distributorId,
      productId,
      products,
      purchaseOrders,
    })
  ), [getDistributorProductHistoryEntryHelper, products, purchaseOrders]);

  const getLatestProductHistoryEntry = useCallback((productId) => (
    getLatestProductHistoryEntryHelper({
      productId,
      products,
      purchaseOrders,
    })
  ), [getLatestProductHistoryEntryHelper, products, purchaseOrders]);

  const getDistributorHistoryProducts = useCallback((distributorId) => (
    getDistributorHistoryProductsHelper({
      distributorId,
      products,
      purchaseOrders,
      buildOrderDraftItem,
    })
  ), [getDistributorHistoryProductsHelper, products, purchaseOrders, buildOrderDraftItem]);

  const handleDistributorInputChange = useCallback((value) => {
    const match = resolveSupplierByInput(value);
    setOrderFormData((prev) => {
      const nextSupplierId = match ? String(match.id) : '';
      const nextDistributorId = match ? String(match.distributor_id || '') : '';
      const distributorName = match
        ? (distributorById.get(String(match.distributor_id || ''))?.name || '')
        : '';
      const previousSupplierId = String(prev?.supplier_id || '').trim();
      const distributorChanged = previousSupplierId !== nextSupplierId;
      return {
        ...prev,
        supplier_id: nextSupplierId,
        supplier_name: value,
        distributor_id: nextDistributorId,
        distributor_name: distributorName,
        items: distributorChanged
          ? [createEmptyOrderItem()]
          : prev.items,
      };
    });
  }, [createEmptyOrderItem, distributorById, resolveSupplierByInput, setOrderFormData]);

  return {
    resolveSupplierByInput,
    resolveProductByInput,
    getDistributorProductOptions,
    getDistributorProductHistoryEntry,
    getLatestProductHistoryEntry,
    getDistributorHistoryProducts,
    handleDistributorInputChange,
  };
};

export default usePurchaseLookups;

